/// Every typed compatibility constructor is checked against independent JSON trees and schema boundary failures.
@Suite struct WebhookCompatibilityTests {
    /// Exercises GithubAuthor defaults, complete values, nullable fields and every documented local field bound.
    /// - Throws: Unexpected valid constructors fail this test; invalid null/length/count/URI/color inputs are asserted.
    @Test func webhookGitHubAuthor() throws {
        #expect((try WebhookGitHubAuthor(name: "sample")).jsonValue() == (try JSONValue.parse(Data(##"{"name":"sample"}"##.utf8))))
        #expect((try WebhookGitHubAuthor(username: .value("sample"), name: "sample")).jsonValue() == (try JSONValue.parse(Data(##"{"username":"sample","name":"sample"}"##.utf8))))
        #expect((try WebhookGitHubAuthor(username: .null, name: "sample")).jsonValue() == (try JSONValue.parse(Data(##"{"username":null,"name":"sample"}"##.utf8))))
        #expect(throws: DiscordError.validation(.invalidValue)) { try WebhookGitHubAuthor(username: .value(String(repeating: "x", count: 152134)), name: "sample") }
        _ = try WebhookGitHubAuthor(username: .value(String(repeating: "x", count: 152133)), name: "sample")
        #expect(throws: DiscordError.validation(.invalidValue)) { try WebhookGitHubAuthor(name: String(repeating: "x", count: 152134)) }
        _ = try WebhookGitHubAuthor(name: String(repeating: "x", count: 152133))
    }

