        #expect(throws: DiscordError.validation(.invalidValue)) { try WebhookGitHubCheckRun(name: "sample", htmlURL: "https://example.com/a", checkSuite: try WebhookGitHubCheckSuite(headSha: "sample", app: try WebhookGitHubCheckApp(name: "sample")), detailsURL: .value("relative")) }
